        if (onlinePeers.has(uuid)) {
            // 在线 → 自动发送连接请求
            connectToPeer(uuid, contact.name, contact.ip);
        } else {
            // 离线 → 提示用户，但仍然加载历史聊天记录
            showToast('对方不在线');
            openChat(uuid);
        }
    });
    // 右键删除
    div.addEventListener('contextmenu', (e) => {
        e.preventDefault();
        if (confirm(`确定删除联系人 ${contact.name} 及聊天记录？`)) {
            deleteContact(uuid);
        }
    });
    contactsList.appendChild(div);
}

