355	/**
356	 * 统一处理文件请求响应。
357	 * 发送方会从聊天 WS 直连或控制 WS 两条路径收到此消息，
358	 * 通过 transfer_id 精确匹配，且幂等（started 标记防止重复启动上传）。
359	 */
360	function handleFileRequestResponse(msg) {
361	    const transferId = msg.transfer_id;
362	    const t = pendingFileTransfers[transferId];
363	    if (!t) return; // 不是我们的传输
364	
365	    if (msg.accepted) {
366	        if (t.started) return; // 已启动，幂等
367	        t.started = true;
368	        startChunkUpload(transferId);
369	    } else {
370	        // 对方拒绝
371	        delete pendingFileTransfers[transferId];
372	        const fileMsg = findFileMsgByTransferId(transferId);
373	        if (fileMsg) {
374	            fileMsg.status = 'failed';
375	            // 通过 transferId 找到对应的联系人 uuid
376	            saveFileMessage(t.uuid, fileMsg);
377	            if (currentChat) renderMessages(currentChat);
378	        }
379	        showToast('对方拒绝了文件传输');
380	    }
381	}
