1168	/**
1169	 * 开始分片上传文件到对方后端。
1170	 * 每发送一个分片后更新聊天气泡中的进度。
1171	 */
1172	async function startChunkUpload(transferId) {
1173	    const t = pendingFileTransfers[transferId];
1174	    if (!t) return;
1175	
1176	    const fileMsg = findFileMsgByTransferId(transferId);
1177	    if (fileMsg) {
1178	        fileMsg.status = 'uploading';
1179	        saveFileMessage(t.uuid, fileMsg);
1180	        if (currentChat === t.uuid) renderMessages(t.uuid);
1181	    }
1182	
1183	    const peer = onlinePeers.get(t.uuid);
1184	    if (!peer) {
1185	        showToast('对方不在线，无法发送文件');
1186	        if (fileMsg) {
1187	            fileMsg.status = 'failed';
1188	            saveFileMessage(t.uuid, fileMsg);
1189	            if (currentChat === t.uuid) renderMessages(t.uuid);
1190	        }
1191	        delete pendingFileTransfers[transferId];
1192	        return;
1193	    }
1194	
1195	    const file = t.file;
1196	    const CHUNK_SIZE = t.CHUNK_SIZE;
1197	    const totalChunks = t.totalChunks;
1198	    const peerPort = peer.ws_port || 50002;
1199	
1200	    for (let i = t.currentChunk; i < totalChunks; i++) {
1201	        const start = i * CHUNK_SIZE;
1202	        const end = Math.min(start + CHUNK_SIZE, file.size);
1203	        const blob = file.slice(start, end);
1204	        const dataB64 = await readAsBase64(blob);
1205	
1206	        let retries = 0;
1207	        let success = false;
1208	
1209	        while (retries < 3 && !success) {
1210	            try {
1211	                const resp = await fetch(`http://${peer.ip}:${peerPort}/api/transfer/chunk`, {
1212	                    method: 'POST',
1213	                    headers: { 'Content-Type': 'application/json' },
1214	                    body: JSON.stringify({
1215	                        transfer_id: transferId,
1216	                        chunk_index: i,
1217	                        data: dataB64,
1218	                    }),
1219	                });
1220	                if (resp.ok) {
1221	                    success = true;
1222	                    t.currentChunk = i + 1;
1223	                    // 更新进度条
1224	                    if (fileMsg) {
1225	                        fileMsg.progress = Math.round((i + 1) / totalChunks * 100);
1226	                        if (currentChat === t.uuid) renderMessages(t.uuid);
1227	                    }
1228	                } else {
1229	                    retries++;
1230	                }
1231	            } catch (e) {
1232	                retries++;
1233	            }
1234	        }
1235	
1236	        if (!success) {
1237	            if (fileMsg) {
1238	                fileMsg.status = 'failed';
1239	                saveFileMessage(t.uuid, fileMsg);
1240	                if (currentChat === t.uuid) renderMessages(t.uuid);
1241	            }
1242	            delete pendingFileTransfers[transferId];
1243	            return; // 传输中断
1244	        }
1245	    }
1246	
1247	    // 所有分片发送完毕 → 通知对方合并
1248	    try {
1249	        await fetch(`http://${peer.ip}:${peerPort}/api/transfer/complete`, {
1250	            method: 'POST',
1251	            headers: { 'Content-Type': 'application/json' },
1252	            body: JSON.stringify({ transfer_id: transferId }),
1253	        });
1254	        if (fileMsg) {
1255	            fileMsg.status = 'complete';
1256	            fileMsg.progress = 100;
1257	            saveFileMessage(t.uuid, fileMsg);
1258	            if (currentChat === t.uuid) renderMessages(t.uuid);
1259	        }
1260	    } catch (e) {
1261	        if (fileMsg) {
1262	            fileMsg.status = 'failed';
1263	            saveFileMessage(t.uuid, fileMsg);
1264	            if (currentChat === t.uuid) renderMessages(t.uuid);
1265	        }
1266	    }
1267	
1268	    delete pendingFileTransfers[transferId];
1269	}
