1271	function readAsBase64(blob) {
1272	    return new Promise((resolve) => {
1273	        const reader = new FileReader();
1274	        reader.onloadend = () => {
1275	            const result = reader.result;
1276	            // 去掉 "data:...;base64," 前缀
1277	            const b64 = result.split(',')[1] || result;
1278	            resolve(b64);
1279	        };
1280	        reader.readAsDataURL(blob);
1281	    });
1282	}
